 "content": "def transform(grid):
    out = [row[:] for row in grid]
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]

    # Find vertically separated active bands.
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    # Match rows of the two repeated bands. A row with a long foreground
    # continuation to the right edge supplies the missing suffix in its mate.
    a, b = bands[0], bands[1]
    for ra, rb in zip(a, b):
        rowa, rowb = grid[ra], grid[rb]
        def tail_start(row):
            c = len(row) - 1
            if row[c] == bg:
                return len(row)
            while c >= 0 and row[c] != bg:
                c -= 1
            return c + 1

        ta, tb = tail_start(rowa), tail_start(rowb)
        lena, lenb = len(rowa) - ta, len(rowb) - tb
        # Need a genuine run (not an isolated edge pixel); use the longer
        # edge-reaching run as the reference pattern.
        if max(lena, lenb) < 3 or lena == lenb:
            continue
        if lena > lenb:
            source, target, tr = rowa, rowb, rb
        else:
            source, target, tr = rowb, rowa, ra
        last = max((c for c, v in enumerate(target) if v != bg), default=-1)
        # Extend only the target's blank suffix where the reference has
        # foreground, preserving all original cells.
        for c in range(last + 1, len(target)):
            if target[c] == bg and source[c] != bg:
                out[tr][c] = 1
    return out
