        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    # Corresponding rows in the two copies sometimes have an incomplete
    # horizontal tail. If one copy continues to the right edge in the motif
    # color while its counterpart has a blank suffix, mark that suffix with 1.
    upper, lower = bands[0], bands[1]
    for ra, rb in zip(upper, lower):
        for source_r, target_r in ((ra, rb), (rb, ra)):
            source = grid[source_r]
            target = grid[target_r]
            source_start = len(source)
            while source_start > 0 and source[source_start - 1] != bg:
                source_start -= 1
            target_start = len(target)
            while target_start > 0 and target[target_start - 1] == bg:
                target_start -= 1
            # A visible continuation of at least three cells distinguishes
            # the deliberate extension from incidental terminal pixels.
            if len(source) - source_start >= 3 and len(target) - target_start >= 3:
                for c in range(target_start, len(target)):
                    if target[c] == bg:
                        out[target_r][c] = 1
