    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out

    from collections import Counter
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    active_rows = [r for r, row in enumerate(grid) if any(value != background for value in row)]
    bands = []
    for r in active_rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    width = len(grid[0])
    for ra, rb in zip(bands[0], bands[1]):
        a, b = grid[ra], grid[rb]
        enda = max((c for c, v in enumerate(a) if v != background), default=-1)
        endb = max((c for c, v in enumerate(b) if v != background), default=-1)
        if enda == endb or min(enda, endb) < 0:
            continue

        # The shorter copy is the incomplete one. Infer its horizontal phase
        # relative to the longer template from the shared prefix.
        if enda > endb:
            source, target_r, target_end = a, rb, endb
        else:
            source, target_r, target_end = b, ra, enda
        target = grid[target_r]
        best_shift, best_score = 0, -1
        for shift in range(-3, 4):
            score = 0
            for c in range(target_end + 1):
                sc = c - shift
                if 0 <= sc < width and target[c] == source[sc]:
                    score += 1
            if score > best_score:
                best_shift, best_score = shift, score
        for c in range(target_end + 1, width):
            sc = c - best_shift
            if 0 <= sc < width and target[c] == background and source[sc] != background:
                out[target_r][c] = 1
    return out
