    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    # Compare the second repeated panel with the full first panel, using the
    # exact horizontal periodicity (3 columns per motif unit). The lower panel
    # begins with a complete 3x3 pattern and then has a blank continuation.
    first, second = bands[0], bands[1]
    width = len(grid[0])
