    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    # In each panel, rows 0 and 2 of the 4-row glyph block are the same
    # horizontal motif at a three-column period. The second panel's row 0 is
    # the incomplete one; continue its visible 3x3 motif across the suffix.
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r,row in enumerate(grid) if any(v != background for v in row)]
    bands=[]
    for r in active:
        if not bands or r > bands[-1][-1]+1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands)<2:
        return out
    r=bands[1][0]
    row=grid[r]
    # Repeating foreground blocks are separated by two blank columns. Extend
    # the motif's visible phase, marking inferred foreground cells as 1.
    motif_start=next((c for c,v in enumerate(row) if v != background),None)
    if motif_start is None:
        return out
    for c in range(motif_start, len(row)):
        if row[c] == background and c >= motif_start+3:
            prior=c-3
            if prior>=0 and row[prior]!=background:
                out[r][c]=1
    return out

