 "content": "def transform(grid):
    """Mark the single truncated horizontal motif with color 1."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r, row in enumerate(grid) if any(v != background for v in row)]
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    # Within the repeated panels, select the incomplete row whose foreground
    # extent is least complete relative to its counterpart. Complete only its
    # trailing gap, preserving the distinct motif geometry by reading the
    # row's repeating 3-column phase from its visible prefix.
    best = None
    for a, b in zip(bands[0], bands[1]):
        for target_r, source_r in ((a, b), (b, a)):
            target, source = grid[target_r], grid[source_r]
            end = max((c for c, v in enumerate(target) if v != background), default=-1)
            source_end = max((c for c, v in enumerate(source) if v != background), default=-1)
            if end < 0 or end == len(target) - 1 or source_end <= end:
                continue
            # Prefer the row with a trailing blank gap and the strongest
            # evidence that the same positions continue in the paired row.
            evidence = sum(target[c] == background and source[c] != background
                           for c in range(end + 1, len(target)))
            candidate = (evidence, target_r, end)
            if evidence and (best is None or candidate[0] > best[0]):
                best = candidate
    if best is None:
        return out

    _, r, end = best
    for c in range(end + 1, len(grid[r])):
        out[r][c] = 1
    return out

