    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r, row in enumerate(grid) if any(v != background for v in row)]
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    # The lower panel repeats the upper panel's motif. Identify the horizontal
    # translation from overlapping foreground cells, then mark the continued
    # motif cells in the lower panel's blank trailing region.
    upper, lower = bands[0], bands[1]
    width = len(grid[0])
    best_shift, best_score = 0, -1
    for shift in range(-4, 5):
        score = 0
        for ru, rl in zip(upper, lower):
            last = max((c for c, v in enumerate(grid[rl]) if v != background), default=-1)
            for c in range(last + 1):
                uc = c - shift
                if 0 <= uc < width and grid[rl][c] == grid[ru][uc]:
                    score += 1
        if score > best_score:
            best_score, best_shift = score, shift

    for ru, rl in zip(upper, lower):
        row = grid[rl]
        last = max((c for c, v in enumerate(row) if v != background), default=-1)
        for c in range(last + 1, width):
            uc = c - best_shift
            if 0 <= uc < width and row[c] == background and grid[ru][uc] != background:
                out[rl][c] = 1
    return out

